export type CuaPermissionKind = "accessibility" | "screen_recording";

export interface OpenCuaPermissionOnboardingOptions {
  /// Opaque id generated by the renderer per call; closing that permission surface cancels only this participant.
  operationId?: string;
  initialPermission?: CuaPermissionKind;
  /// Permissions whose fresh-state confirmation is still missing; main opens each settings page and waits for the app return.
  requiredPermissions?: CuaPermissionKind[];
}

export interface CuaAccessibilitySettingsResult {
  success: boolean;
  canceled?: boolean;
  /// Main-level onboarding session id; concurrent windows of one Helper identity share it.
  sessionId?: string;
  /// True only after every staged settings page observed any ZCode window return.
  returnedFromSettings?: boolean;
  /**
   * Several windows may join one main onboarding session. Exactly one call per renderer/host gets true and must
   * restart that host's Helper; the same renderer's repeats get false. Not one global winner: every window has its
   * own host/Helper, and pre-authorization processes each need their own recovery.
   * undefined is the legacy-main shape, treated as a single-window owner.
   */
  restartHelperAfterReturn?: boolean;
  error?: string;
}

/**
 * Drag warm-up result (the renderer-visible shape).
 *
 * Note `helperBundleFingerprint` is deliberately **not declared here**: it is the main process's synchronous TOCTOU
 * evidence in memory (compared at dragstart for "bytes unchanged since self-verify"); exposing it over IPC is useless
 * and widens the attack surface. The main-side PrepareCuaHelperPermissionDragMainResult carries it, stripped before the handler returns.
 */
export interface PrepareCuaHelperPermissionDragResult {
  success: boolean;
  error?: string;
  helperAppPath?: string;
  helperDisplayName?: string;
  helperBundleId?: string;
}
